  "filename": "script.js",
  "content": "(function(){
  const API_BASE = '/api';

  function apiRequest(method, path, data){
    const options = {
      method,
      headers: {'Content-Type':'application/json'}
    };
    if(data !== undefined){
      options.body = JSON.stringify(data);
    }
    return fetch(API_BASE + path, options).then(res => {
      if(!res.ok){
        return res.json().catch(() => ({error:'Network error'})).then(err => { throw err; });
      }
      return res.json();
    });
  }

  function showToast(message, type='error'){
    let container = document.getElementById('toast-container');
    if(!container){
      container = document.createElement('div');
      container.id = 'toast-container';
      container.style.position = 'fixed';
      container.style.bottom = '1rem';
      container.style.right = '1rem';
      container.style.zIndex = '1000';
      document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.textContent = message;
    toast.style.background = type === 'error' ? '#e74c3c' : '#2ecc71';
    toast.style.color = '#fff';
    toast.style.padding = '0.75rem 1rem';
    toast.style.marginTop = '0.5rem';
    toast.style.borderRadius = '4px';
    toast.style.boxShadow = '0 2px 6px rgba(0,0,0,0.2)';
    container.appendChild(toast);
    setTimeout(() => { toast.remove(); }, 4000);
  }

  const pages = {};

  window.ForgeAI = {
    registerPage: function(slug, renderer){
      pages[slug] = renderer;
    }
  };

  async function renderHome({root, api}){
    const form = document.getElementById('note-form');
    const titleInput = document.getElementById('title');
    const contentInput = document.getElementById('content');
    const loadingEl = document.getElementById('loading');
    const errorEl = document.getElementById('error');
    const emptyEl = document.getElementById('empty-state');
    const listSection = document.getElementById('note-list-section');

    function setLoading(show){
      loadingEl.classList.toggle('hidden', !show);
    }
    function setError(msg){
      errorEl.textContent = msg;
      errorEl.classList.toggle('hidden', !msg);
    }
    function renderList(notes){
      let ul = document.getElementById('note-list');
      if(ul){ ul.remove(); }
      if(notes.length === 0){
        emptyEl.classList.remove('hidden');
        return;
      }
      emptyEl.classList.add('hidden');
      ul = document.createElement('ul');
      ul.id = 'note-list';
      ul.style.listStyle = 'none';
      ul.style.padding = '0';
      notes.forEach(note => {
        const li = document.createElement('li');
        li.style.border = '1px solid #ddd';
        li.style.padding = '0.5rem';
        li.style.marginBottom = '0.5rem';
        const title = document.createElement('h3');
        title.textContent = note.title;
        const content = document.createElement('p');
        content.textContent = note.content || '';
        const delBtn = document.createElement('button');
        delBtn.textContent = 'Delete';
        delBtn.style.marginTop = '0.5rem';
        delBtn.addEventListener('click', async () => {
          try {
            await apiRequest('DELETE', `/notes/${note.id}`);
            loadNotes();
          } catch(err){
            showToast(err.error || 'Failed to delete note');
          }
        });
        li.appendChild(title);
        li.appendChild(content);
        li.appendChild(delBtn);
        ul.appendChild(li);
      });
      listSection.appendChild(ul);
    }

    async function loadNotes(){
      setLoading(true);
      setError('');
      try {
        const data = await apiRequest('GET', '/notes');
        renderList(data.notes || []);
      } catch(err){
        setError(err.error || 'Failed to load notes');
      } finally {
        setLoading(false);
      }
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const title = titleInput.value.trim();
      const content = contentInput.value.trim();
      if(!title){
        showToast('Title must not be empty');
        return;
      }
      try {
        await apiRequest('POST', '/notes', {title, content});
        form.reset();
        loadNotes();
        showToast('Note added', 'success');
      } catch(err){
        showToast(err.error || 'Failed to add note');
      }
    });

    loadNotes();
  }

  function renderNotFound({root}){
    root.innerHTML = '<h2>Page not found</h2>';
  }

  function router(){
    const hash = location.hash.slice(1) || 'home';
    const renderer = pages[hash] || renderNotFound;
    const root = document.getElementById('app');
    renderer({root, api: {request: apiRequest}});
  }

  window.addEventListener('hashchange', router);
  document.addEventListener('DOMContentLoaded', () => {
    window.ForgeAI.registerPage('home', renderHome);
    router();
  });
})();
"
}
